export const meta = {
  name: 'create-spec',
  description: 'Detect stack → research (codebase + web + docs) → synthesize → persist an execution-ready spec for a single feature, across one or more repos',
  whenToUse: 'When a feature needs formal planning before implementation. Auto-detects the stack from the stack manifests and supports split backend+frontend repos. Sizes the work first (XS returns no spec). Produces a draft spec under .ai/specs/ plus open questions from a fresh-context clarity gate; after human approval hand its id to ship-feature {spec:"<id>"} or /execute-task.',
  phases: [
    { title: 'Detect', detail: 'Identify stack(s) and repo layout', model: 'sonnet' },
    { title: 'Classify', detail: 'Type, size (XS/S/M/L), domains, keywords; XS stops here', model: 'opus' },
    { title: 'Research', detail: 'Codebase (per repo) + web + docs/context', model: 'opus' },
    { title: 'Synthesize', detail: 'Business rules, acceptance criteria, tasks, decisions', model: 'opus' },
    { title: 'Document', detail: 'Write the size-appropriate spec files to .ai/specs/', model: 'opus' },
    { title: 'Clarify', detail: 'Fresh-context clarity gate: record hidden assumptions as open questions', model: 'opus' },
  ],
}

const WRITER_AGENT = 'general-purpose'

const isObj = args && typeof args === 'object'
const description = typeof args === 'string' ? args : (isObj && args.description) || ''
const typeHint = (isObj && args.type) || null
const priority = (isObj && args.priority) || 'P2'
const repoHints = (isObj && args.repos) || null
const answers = (isObj && args.answers) || null
const ticket = (isObj && args.ticket) || ((description.match(/^\s*([A-Z][A-Z0-9]+-\d+)\b/) || [])[1]) || null
const force = !!(isObj && args.force)

if (!description) {
  log('Provide a feature description (string) or { description, type, priority, repos, answers }.')
  return { error: 'missing description' }
}

